from pathlib import Path
p=Path('index.html')
s=p.read_text(encoding='utf-8')
a=s.index(' if(raw==="properties"){')
b=s.index(' if(raw==="unknown_component")',a)
s=s[:a]+" if(raw===\"properties\"){\n  const live=stageOverride===null&&blockSession?.kind===\"g3quiz\"&&blockSession.key===\"g3:properties\";\n  return g3PropertiesQuestion(d,live?blockSession.done:null);\n }\n"+s[b:]
anchor='function g3UnitNumberQuestion('
assert s.count(anchor)==1
s=s.replace(anchor,"const G3_PROPERTIES_VARIANTS=[\n [\"commAdd\",\"commMul\"],\n [\"assocAdd\",\"assocMul\"],\n [\"addGroup\",\"mulGroup\",\"pairGroups\"]\n];\nfunction g3PropertiesQuestion(stage,slot=null){\n const d=Math.max(0,Math.min(2,Number(stage)||0)),variants=G3_PROPERTIES_VARIANTS[d],\n  v=slot===null?g6RandomFrom(variants):variants[((slot%variants.length)+variants.length)%variants.length];\n const input=(text,answer,ex,key,extra={})=>g6NumberInputQuestion(text,answer,ex,\n  \"g3:properties:\"+d+\":\"+v+\":\"+key,\n  {inputHint:\"Введи целое число.\",audit:{type:\"g3Properties\",variant:v,...extra,answer:rational(answer,1)}});\n if(v===\"commAdd\"||v===\"commMul\"){\n  const a=ri(2,90),b=ri(2,9),mul=v===\"commMul\";\n  const sign=mul?\" · \":\" + \";\n  return input(\"Найди пропущенное число: <b>\"+a+sign+b+\" = \"+b+sign+\"□</b>\",\n   a,\"Переместительное свойство: \"+a+sign+b+\" = \"+b+sign+\"<b>\"+a+\"</b>.\",\n   a+\":\"+b,{a,b});\n }\n if(v===\"assocAdd\"){\n  const a=ri(10,80),b=ri(10,90),c=100-b,answer=a+b+c;\n  return input(\"Вычисли удобным способом: <b>(\"+a+\" + \"+b+\") + \"+c+\"</b> = ?\",\n   answer,\"Объедини слагаемые \"+b+\" и \"+c+\": \"+b+\" + \"+c+\" = 100.<br>\"+a+\" + 100 = <b>\"+answer+\"</b>.\",\n   a+\":\"+b+\":\"+c,{a,b,c});\n }\n if(v===\"assocMul\"){\n  const a=g6RandomFrom([2,5]),b=ri(2,9),c=10/a,answer=a*b*c;\n  return input(\"Вычисли удобным способом: <b>(\"+a+\" · \"+b+\") · \"+c+\"</b> = ?\",\n   answer,\"Перегруппируем множители: (\"+a+\" · \"+c+\") · \"+b+\" = 10 · \"+b+\" = <b>\"+answer+\"</b>.\",\n   a+\":\"+b+\":\"+c,{a,b,c});\n }\n if(v===\"addGroup\"){\n  const a=ri(20,90),b=ri(15,85),c=100-b,d=ri(11,80),answer=a+b+c-d;\n  return input(\"Сначала найди удобную пару: <b>\"+a+\" + \"+b+\" + \"+c+\" − \"+d+\"</b> = ?\",\n   answer,b+\" + \"+c+\" = 100.<br>\"+a+\" + 100 − \"+d+\" = <b>\"+answer+\"</b>.\",\n   a+\":\"+b+\":\"+c+\":\"+d,{a,b,c,d});\n }\n if(v===\"mulGroup\"){\n  const a=g6RandomFrom([2,5]),b=ri(2,9),c=10/a,d=ri(11,59),answer=a*b*c+d;\n  return input(\"Вычисли: <b>\"+a+\" · \"+b+\" · \"+c+\" + \"+d+\"</b> = ?\",\n   answer,\"Сначала \"+a+\" · \"+c+\" = 10, затем 10 · \"+b+\" = \"+(10*b)+\n   \".<br>\"+(10*b)+\" + \"+d+\" = <b>\"+answer+\"</b>.\",\n   a+\":\"+b+\":\"+c+\":\"+d,{a,b,c,d});\n }\n const a=ri(2,9),b=ri(2,9),answer=10*a+10*b;\n return input(\"Вычисли, перегруппировав множители: <b>2 · \"+a+\" · 5 + 5 · \"+b+\" · 2</b> = ?\",\n  answer,\"2 · 5 = 10 и 5 · 2 = 10.<br>10 · \"+a+\" + 10 · \"+b+\" = <b>\"+answer+\"</b>.\",\n  a+\":\"+b,{a,b});\n}\n\n"+anchor)
assert s.count('function g3PropertiesQuestion(')==1
p.write_text(s,encoding='utf-8')
print('patched properties length',len(s))
